import{_ as a,o as s,c as t,ah as n}from"./chunks/framework.Be4_4mPW.js";const p=JSON.parse('{"title":"Phase 2: a game you can design, publish and play","description":"","frontmatter":{"title":"Phase 2: a game you can design, publish and play","date":"2026-10-25T00:00:00.000Z","phase":2,"status":"gate"},"headers":[],"relativePath":"blog/phase-2-features.md","filePath":"blog/phase-2-features.md"}'),o={name:"blog/phase-2-features.md"};function i(r,e,h,l,d,c){return s(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="phase-2-a-game-you-can-design-publish-and-play" tabindex="-1">Phase 2: a game you can design, publish and play <a class="header-anchor" href="#phase-2-a-game-you-can-design-publish-and-play" aria-label="Permalink to &quot;Phase 2: a game you can design, publish and play&quot;">​</a></h1><p>Phase 1 built the plumbing. Phase 2 put screens on it. The demo on the home page is now a working game. An admin designs it, publishes it to the server and runs it as the umpire. Players log in and talk in rooms arranged however they like.</p><h2 id="what-there-is-now" tabindex="-1">What there is now <a class="header-anchor" href="#what-there-is-now" aria-label="Permalink to &quot;What there is now&quot;">​</a></h2><ul><li><strong>The design editor.</strong> The admin builds the game: forces, roles, rooms and who may read or write in each, plus themes and each force&#39;s objectives. A live table shows every role&#39;s access to every room before anything is published.</li><li><strong>Publishing.</strong> One button turns the design into accounts, rooms and documents on the server. The plan shows what will change, grouped and collapsed, and steps that remove things need a tick. Publishing again changes only what differs.</li><li><strong>Audit and repair.</strong> A check compares the live server with the design and offers repairs, so a step that went wrong does not leave access quietly broken.</li><li><strong>The player&#39;s screen.</strong> A welcome page and login, then a workspace of dockable room tabs that each player arranges and the browser remembers. On the right, a column holds announcements from the admin and the player&#39;s force panel with its objectives.</li><li><strong>Chat.</strong> Messages are grouped by sender with date dividers, long histories load as you scroll, and unread counts show on the tabs. Message text is always shown as plain text.</li><li><strong>The umpire.</strong> The admin plays as umpire in the White Force: it sees and writes in every room and can amend any force&#39;s objectives live. White Force observers can read but never post.</li><li><strong>The multi-client view.</strong> Two to four players side by side in one window, each with their own login, so one person can demonstrate a whole game. The demo database can be reset, exported and imported.</li></ul><h2 id="how-it-was-checked" tabindex="-1">How it was checked <a class="header-anchor" href="#how-it-was-checked" aria-label="Permalink to &quot;How it was checked&quot;">​</a></h2><p>Every feature has browser tests that run on each change, and anything that touches access is also tested against a real ejabberd server. Before this gate, a reviewer read the access and publishing code. That review found problems, including a case where changing a role to read only could leave it able to post if a later step failed. All of them are fixed and covered by tests. The screenshots on each pull request are checked to come out identical on a second run, so a change in a picture means a change in the app.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>Only Chromium is tested. Firefox and Safari come in Phase 3, along with performance at scale and a full accessibility audit.</li><li>In narrow panes, such as the multi-client view on a small screen, the out-of-game column takes too much room. It will become a tab of its own when space is short.</li><li>Unread counts start again at each login.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p>Phase 3 runs the full end-to-end scenarios on both backends, measures performance and accessibility, installs the reference deployment on real hardware, and ends with the v1 release.</p>',10)])])}const m=a(o,[["render",i]]);export{p as __pageData,m as default};
